import {documentContent,basePrice} from './one-off-core.js';
import {DEFAULT_PROVIDER} from './contract-core.js?v=20261024-policy';
import {renderDocument} from './contract-pdf.js?v=20261024-policy';
const form=document.querySelector('#one-document'),$=id=>document.getElementById(id);let busy=false,url,libraries;
function collect(){return {...Object.fromEntries([...form.querySelectorAll('[name]')].map(el=>[el.name,el.type==='checkbox'?el.checked:el.value.trim()])),...DEFAULT_PROVIDER};}
function invalidate(){if(url)URL.revokeObjectURL(url);url=null;$('document-result').hidden=true;$('document-download').removeAttribute('href');$('document-open').removeAttribute('href');$('document-status').textContent='';}
function update(){const kind=$('documentType').value;for(const section of document.querySelectorAll('[data-services]')){const visible=section.dataset.services===$('service').value;section.hidden=!visible;section.querySelectorAll('input').forEach(el=>el.disabled=!visible);}try{$('base-price').textContent='基本料金の目安：'+basePrice(collect()).toLocaleString('ja-JP')+'円〜。追加作業・実費を確認し、総額は別途合意します。';}catch{$('base-price').textContent='サービスと完成尺／ページ数を確認してください。';}for(const section of document.querySelectorAll('[data-kinds]')){const visible=section.dataset.kinds.split(' ').includes(kind);section.hidden=!visible;section.querySelectorAll('input,textarea').forEach(el=>el.disabled=!visible);}const political=$('category').value==='political';$('political-warning').hidden=!political;$('make-document').disabled=busy||political||Boolean(url);$('agreed').required=kind!=='estimate';$('agreementReference').required=['invoice','receipt'].includes(kind);$('paymentVerified').required=kind==='receipt';}
function load(src,name){if(globalThis[name])return Promise.resolve(globalThis[name]);return new Promise((resolve,reject)=>{const s=document.createElement('script');const timer=setTimeout(()=>{s.remove();reject(Error('PDF準備がタイムアウトしました。'));},30000);s.src=src;s.onload=()=>{clearTimeout(timer);globalThis[name]?resolve(globalThis[name]):reject(Error('PDFライブラリが読み込めません。'));};s.onerror=()=>{clearTimeout(timer);s.remove();reject(Error('PDFライブラリを取得できません。'));};document.head.append(s);});}
async function dependencies(){if(!libraries)libraries=Promise.all([load('vendor/pdf-lib-1.17.1.min.js','PDFLib'),load('vendor/fontkit-1.1.1.min.js','fontkit'),fetch('assets/fonts/NotoSansJP-Regular.ttf',{signal:AbortSignal.timeout(30000)}).then(r=>{if(!r.ok)throw Error('フォントを取得できません。');return r.arrayBuffer();})]).then(([PDFLib,fontkit,bytes])=>({PDFLib,fontkit,fontBytes:new Uint8Array(bytes)})).catch(e=>{libraries=null;throw e;});return libraries;}
form.addEventListener('input',e=>{if(busy)return;invalidate();$('document-error').textContent='';if(e.target.id!=='reviewed')$('reviewed').checked=false;if(!['documentType','sample','reviewed','agreed','paymentVerified'].includes(e.target.id)){$('agreed').checked=false;$('paymentVerified').checked=false;}update();});
form.addEventListener('change',()=>{if(!busy){invalidate();update();}});
form.addEventListener('submit',async e=>{e.preventDefault();if(busy||url||!form.reportValidity())return;let content;try{content=documentContent(collect());}catch(error){$('document-error').textContent=error.message;return;}invalidate();busy=true;const enabled=[...form.querySelectorAll('input,textarea,select,button')].filter(el=>!el.disabled);enabled.forEach(el=>el.disabled=true);$('document-status').textContent='端末内でPDFを作成しています。';try{const bytes=await renderDocument(content,await dependencies());url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));$('document-download').href=url;$('document-download').download=content.documentTitle+'_'+content.data.issueDate+'.pdf';$('document-open').href=url;$('document-result').hidden=false;$('document-status').textContent='PDFを作成しました。送付・署名・入金照合は行っていません。保存前に内容と重複発行がないことを確認してください。';$('document-download').click();}catch(error){$('document-error').textContent='作成できませんでした。'+error.message;$('document-status').textContent='入力内容は画面に残っています。';}finally{busy=false;enabled.forEach(el=>el.disabled=false);update();}});
$('issueDate').value=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('document-fields').disabled=false;update();
